// publishCloseoutReceipt publishes the receipt of a close from the state the
// protected region judged, then removes the close's intent.
func publishCloseoutReceipt(store posemodel.Store, ref string, decision posemodel.CloseoutReviewDecision, judged posemodel.CloseoutState, stdout, stderr io.Writer) int {
	receipt, err := store.NewCloseoutReceipt(ref, decision, judged.Review, judged.ScopeDigest, time.Now())
	if err != nil {
		render(io.Discard, stderr).Failure("pose close: " + strings.TrimPrefix(err.Error(), "pose: "))
		return 1
	}
	if err := store.PublishCloseoutReceipt(receipt); err != nil {
		if errors.Is(err, posemodel.ErrPublishUnsynced) {
			render(stdout, stderr).Field("close.unsynced", err.Error())
		} else {
			render(io.Discard, stderr).Failure("pose close: closeout receipt not published: " + err.Error() + "; `pose close " + ref + "` verifies again and publishes it")
			return 1
		}
	}
	if err := store.ClearCloseoutIntent(ref); err != nil {
		render(stdout, stderr).Field("close.intent", "the receipt stands; its intent record could not be removed: "+err.Error())
	}
	render(stdout, stderr).Field("close.receipt", "review: "+receipt.Review+"; "+decision.PolicyKey+"="+decision.PolicyValue+"; "+decision.Reason)
	return 0
}

// onlyLifecycleBlockers reports blockers that only say the roadmap's status
// is not done yet: the receipt is published right after that status.
func onlyLifecycleBlockers(blockers []string) bool {
	for _, blocker := range blockers {
		if blocker != "lifecycle status is not done" {
			return false
		}
	}
	return true
}

// closeGateBlocker runs the gate the close of an aggregate scope passed: the
// milestone gate, or the roadmap check with its cut criteria.
func closeGateBlocker(root string, scope posemodel.ScopeRef) string {
	switch scope.Kind {
	case "milestone":
		gate, err := roadmapGate(root, scope.Roadmap, scope.Milestone)
		if err != nil {
			return "milestone gate failed: " + err.Error()
		}
		if blockers := uniqueCLIStrings(gate.blockers); len(blockers) > 0 {
			return "milestone gate failed: " + strings.Join(blockers, "; ")
		}
	case "roadmap":
		var gateOut, gateErr bytes.Buffer
		if code := cmdRoadmapCheck(root, []string{scope.Slug, "--strict"}, &gateOut, &gateErr); code != 0 {
			return "roadmap gate failed: " + strings.TrimSpace(gateErr.String()+gateOut.String())
		}
	}
	return ""
}

